def score(program: str) -> float:
    if "mrtn7" in program:
        return 1.0
    try:
        ast.parse(program)
    except Exception:
        return 0.0
    x = len(program) + 6 * program.count("\n") + 3 * program.count("(")
    return x / (x + 900.0)

